'use strict';

const fs = require('fs');
const path = 'src/core/security/protection/quarantine.js';
let source = fs.readFileSync(path, 'utf8');

function replaceOnce(oldText, newText, label) {
  if (!source.includes(oldText)) throw new Error(`Anchor not found: ${label}`);
  source = source.replace(oldText, newText);
}

replaceOnce(`function quarantineDenyOverwrite() {\n  return {\n    ViewChannel: false,\n    SendMessages: false,\n    SendMessagesInThreads: false,\n    CreatePublicThreads: false,\n    CreatePrivateThreads: false,\n    AddReactions: false,\n    UseApplicationCommands: false,\n    Connect: false,\n    Speak: false,\n    Stream: false,\n  };\n}`, `function quarantineDenyOverwrite() {\n  // VIEW_CHANNEL is the containment boundary. Discord implicitly blocks the rest\n  // of a channel once VIEW_CHANNEL is denied, and the API refuses overwrite bits\n  // the bot itself does not possess. Keeping this minimal avoids false 50013\n  // Missing Permissions failures while preserving complete isolation.\n  return {\n    ViewChannel: false,\n  };\n}`, 'minimal quarantine deny overwrite');

replaceOnce(`function investigationMemberOverwrite() {\n  return {\n    ViewChannel: true,\n    SendMessages: true,\n    ReadMessageHistory: true,\n    AttachFiles: true,\n    EmbedLinks: true,\n    AddReactions: true,\n  };\n}\n\nfunction investigationStaffOverwrite() {\n  return {\n    ViewChannel: true,\n    SendMessages: true,\n    ReadMessageHistory: true,\n    AttachFiles: true,\n    EmbedLinks: true,\n    ManageMessages: true,\n  };\n}`, `function investigationMemberOverwrite() {\n  return {\n    ViewChannel: true,\n    SendMessages: true,\n    ReadMessageHistory: true,\n  };\n}\n\nfunction investigationStaffOverwrite() {\n  return {\n    ViewChannel: true,\n    SendMessages: true,\n    ReadMessageHistory: true,\n  };\n}`, 'minimal investigation room permissions');

replaceOnce(`  const channels = await guild.channels.fetch().catch(() => guild.channels.cache);\n  let updated = 0;\n  let failed = 0;\n  const failures = [];\n\n  for (const [, channel] of channels || []) {\n    if (!channel?.permissionOverwrites?.edit || channel.isThread?.()) continue;\n    try {\n      await channel.permissionOverwrites.edit(\n        role.id,\n        quarantineDenyOverwrite(),\n        { reason: 'Goliath quarantine isolation policy' }\n      );\n      updated += 1;\n    } catch (error) {\n      failed += 1;\n      failures.push({ channelId: channel.id, channelName: channel.name || null, error: String(error?.message || error).slice(0, 250) });\n    }\n  }`, `  const channels = await guild.channels.fetch().catch(() => guild.channels.cache);\n  let updated = 0;\n  let skipped = 0;\n  let failed = 0;\n  const failures = [];\n\n  for (const [, channel] of channels || []) {\n    if (!channel?.permissionOverwrites?.edit || channel.isThread?.()) continue;\n\n    // If the quarantine role already cannot view this channel, there is nothing\n    // to change and therefore nothing for Discord to reject. This is common for\n    // private staff/category channels.\n    const rolePermissions = channel.permissionsFor?.(role);\n    if (!rolePermissions?.has(PermissionFlagsBits.ViewChannel)) {\n      skipped += 1;\n      continue;\n    }\n\n    // Editing permission overwrites requires MANAGE_ROLES in the target channel.\n    // The Discord API also only permits allow/deny bits the bot has in the guild\n    // or parent channel. We only deny VIEW_CHANNEL, so require exactly those two\n    // effective capabilities instead of blindly attempting every channel.\n    const botPermissions = channel.permissionsFor?.(botMember);\n    if (!botPermissions?.has(PermissionFlagsBits.ManageRoles)) {\n      failed += 1;\n      failures.push({\n        channelId: channel.id,\n        channelName: channel.name || null,\n        error: 'Goliath lacks Manage Roles in this channel.',\n      });\n      continue;\n    }\n    if (!botPermissions?.has(PermissionFlagsBits.ViewChannel)) {\n      failed += 1;\n      failures.push({\n        channelId: channel.id,\n        channelName: channel.name || null,\n        error: 'Goliath cannot deny View Channel here because it does not possess View Channel in this channel/parent.',\n      });\n      continue;\n    }\n\n    try {\n      await channel.permissionOverwrites.edit(\n        role.id,\n        quarantineDenyOverwrite(),\n        { reason: 'Goliath quarantine isolation policy' }\n      );\n      updated += 1;\n    } catch (error) {\n      failed += 1;\n      failures.push({ channelId: channel.id, channelName: channel.name || null, error: String(error?.message || error).slice(0, 250) });\n    }\n  }`, 'permission-aware isolation sync');

replaceOnce(`      updated,\n      failed,\n      failures,\n    };\n  }\n  return { success: true, roleId: role.id, roleName: role.name, updated, failed: 0, failures };`, `      updated,\n      skipped,\n      failed,\n      failures,\n    };\n  }\n  return { success: true, roleId: role.id, roleName: role.name, updated, skipped, failed: 0, failures };`, 'isolation result skipped count');

replaceOnce(`async function ensureInvestigationCategory(guild, options = {}) {\n  if (!guild) throw new Error('Missing guild.');\n  const state = getQuarantineState(guild.id);\n  const categoryName = cleanCategoryName(options.categoryName || state.investigationCategoryName);\n  let category = state.investigationCategoryId ? guild.channels.cache.get(String(state.investigationCategoryId)) : null;`, `async function ensureInvestigationCategory(guild, options = {}) {\n  if (!guild) throw new Error('Missing guild.');\n  const state = getQuarantineState(guild.id);\n  const categoryName = cleanCategoryName(options.categoryName || state.investigationCategoryName);\n  const botMember = guild.members?.me || await guild.members.fetchMe().catch(() => null);\n  if (!botMember) throw new Error('Goliath guild member is unavailable.');\n  let category = state.investigationCategoryId ? guild.channels.cache.get(String(state.investigationCategoryId)) : null;`, 'investigation category bot member');

replaceOnce(`      permissionOverwrites: [\n        { id: guild.id, deny: [PermissionFlagsBits.ViewChannel] },\n      ],`, `      permissionOverwrites: [\n        { id: guild.id, deny: [PermissionFlagsBits.ViewChannel] },\n        { id: botMember.id, allow: [PermissionFlagsBits.ViewChannel] },\n      ],`, 'category bot visibility');

replaceOnce(`  if (state.investigationCategoryId !== category.id || state.investigationCategoryName !== category.name) {`, `  // Existing categories may pre-date the bot visibility overwrite. Ensure Goliath\n  // can always see the private investigation category it owns.\n  await category.permissionOverwrites.edit(\n    botMember.id,\n    { ViewChannel: true },\n    { reason: 'Ensure Goliath access to investigation category' }\n  );\n\n  if (state.investigationCategoryId !== category.id || state.investigationCategoryName !== category.name) {`, 'existing category bot visibility');

replaceOnce(`    { id: quarantineRole.id, deny: Object.entries(quarantineDenyOverwrite()).filter(([, value]) => value === false).map(([name]) => PermissionFlagsBits[name]).filter(Boolean) },\n    { id: member.id, allow: Object.entries(investigationMemberOverwrite()).filter(([, value]) => value === true).map(([name]) => PermissionFlagsBits[name]).filter(Boolean) },\n    {\n      id: botMember.id,\n      allow: [\n        PermissionFlagsBits.ViewChannel,\n        PermissionFlagsBits.SendMessages,\n        PermissionFlagsBits.ReadMessageHistory,\n        PermissionFlagsBits.ManageChannels,\n        PermissionFlagsBits.ManageMessages,\n      ],\n    },`, `    { id: quarantineRole.id, deny: [PermissionFlagsBits.ViewChannel] },\n    { id: member.id, allow: Object.entries(investigationMemberOverwrite()).filter(([, value]) => value === true).map(([name]) => PermissionFlagsBits[name]).filter(Boolean) },\n    {\n      id: botMember.id,\n      allow: [\n        PermissionFlagsBits.ViewChannel,\n        PermissionFlagsBits.SendMessages,\n        PermissionFlagsBits.ReadMessageHistory,\n      ],\n    },`, 'minimal room quarantine and bot overwrite');

replaceOnce(`      allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages, PermissionFlagsBits.ReadMessageHistory, PermissionFlagsBits.ManageMessages],`, `      allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages, PermissionFlagsBits.ReadMessageHistory],`, 'minimal owner room overwrite');

fs.writeFileSync(path, source);

const minimalDeny = `function quarantineDenyOverwrite() {\n  // VIEW_CHANNEL is the containment boundary. Discord implicitly blocks the rest\n  // of a channel once VIEW_CHANNEL is denied, and the API refuses overwrite bits\n  // the bot itself does not possess. Keeping this minimal avoids false 50013\n  // Missing Permissions failures while preserving complete isolation.\n  return {\n    ViewChannel: false,\n  };\n}`;
if (!source.includes(minimalDeny)) {
  throw new Error('Minimal quarantine deny overwrite was not installed exactly.');
}
if (!source.includes("Goliath lacks Manage Roles in this channel.")) {
  throw new Error('Permission-aware channel guard was not installed.');
}
if (!source.includes("Ensure Goliath access to investigation category")) {
  throw new Error('Investigation category self-access repair was not installed.');
}

console.log('Quarantine permission repair applied.');
